"use client";

import { useEffect } from 'react';
import { useRouter, usePathname } from 'next/navigation';
import { useAuth } from '@/hooks/useAuth';

// Mapeamento de rotas para roles permitidas
const ROUTE_ROLES: Record<string, string[]> = {
  // Rotas administrativas - apenas escola
  '/admin': ['school'],
  '/admin/academica': ['school'],
  '/admin/academica/cursos': ['school'],
  '/admin/academica/turmas': ['school'],
  '/admin/academica/matriculas': ['school'],
  '/admin/academica/candidaturas': ['school'],
  '/admin/academica/horarios': ['school'],
  '/admin/academica/certificacao': ['school'],
  '/admin/docentes': ['school'],
  '/admin/docentes/gerir': ['school'],
  '/admin/docentes/turmas': ['school'],
  '/admin/docentes/relatorios': ['school'],
  '/admin/estudantes': ['school'],
  '/admin/estudantes/gerir': ['school'],
  '/admin/estudantes/transferencias': ['school'],
  '/admin/financeiro': ['school'],
  '/admin/financeiro/propinas': ['school'],
  '/admin/financeiro/pagamentos': ['school'],
  '/admin/financeiro/recibos': ['school'],
  '/admin/financeiro/debitosemultas': ['school'],
  '/admin/financeiro/relatorios': ['school'],
  '/admin/relatorios': ['school'],
  '/admin/relatorios/gerais': ['school'],
  '/admin/relatorios/assistencia': ['school'],
  '/admin/completar-perfil': ['school'],
};

// Função para verificar se a rota requer uma role específica
function getRequiredRoles(pathname: string | null): string[] | null {
  if (!pathname) return null;
  
  // Verificar rota exata
  if (ROUTE_ROLES[pathname]) {
    return ROUTE_ROLES[pathname];
  }
  
  // Verificar rotas que começam com o pathname
  for (const [route, roles] of Object.entries(ROUTE_ROLES)) {
    if (pathname.startsWith(route)) {
      return roles;
    }
  }
  
  // Se não encontrar, retornar null (sem restrição de role)
  return null;
}

interface ProtectedRouteProps {
  children: React.ReactNode;
  requireAuth?: boolean;
  requireCompleteProfile?: boolean; // Para escolas, verificar se perfil está completo
  allowedRoles?: string[]; // Roles permitidas para esta rota (opcional, pode ser inferido do pathname)
}

export function ProtectedRoute({ 
  children, 
  requireAuth = true,
  requireCompleteProfile = true,
  allowedRoles
}: ProtectedRouteProps) {
  const { isAuthenticated, loading, user, profileComplete, checkProfileCompletion } = useAuth();
  const router = useRouter();
  const pathname = usePathname();

  // Determinar roles permitidas
  const requiredRoles = allowedRoles || getRequiredRoles(pathname);

  useEffect(() => {
    if (!loading && requireAuth && !isAuthenticated) {
      router.push('/');
      return;
    }

    // Verificar se a role do usuário é permitida para esta rota
    if (
      !loading && 
      isAuthenticated && 
      user &&
      requiredRoles &&
      requiredRoles.length > 0 &&
      !requiredRoles.includes(user.role)
    ) {
      // Role não permitida - redirecionar para página inicial ou dashboard
      console.warn(`Acesso negado: usuário com role '${user.role}' tentou acessar rota que requer roles: ${requiredRoles.join(', ')}`);
      router.push('/admin');
      return;
    }

    // Se for escola e perfil não estiver completo, redirecionar para completar perfil
    if (
      !loading && 
      isAuthenticated && 
      requireCompleteProfile &&
      user?.role === 'school' && 
      profileComplete === false
    ) {
      router.push('/admin/completar-perfil');
    }
  }, [isAuthenticated, loading, requireAuth, requireCompleteProfile, user, profileComplete, router, requiredRoles]);

  // Verificar perfil ao carregar se for escola
  useEffect(() => {
    if (!loading && isAuthenticated && user?.role === 'school' && profileComplete === null) {
      checkProfileCompletion();
    }
  }, [loading, isAuthenticated, user, profileComplete, checkProfileCompletion]);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-gray-900 dark:border-white mx-auto"></div>
          <p className="mt-4 text-gray-600 dark:text-gray-400">A carregar...</p>
        </div>
      </div>
    );
  }

  if (requireAuth && !isAuthenticated) {
    return null;
  }

  // Verificar role antes de renderizar
  if (
    user &&
    requiredRoles &&
    requiredRoles.length > 0 &&
    !requiredRoles.includes(user.role)
  ) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <h2 className="text-2xl font-bold text-red-600 mb-4">Acesso Negado</h2>
          <p className="text-gray-600 dark:text-gray-400">
            Você não tem permissão para acessar esta página.
          </p>
          <p className="text-sm text-gray-500 mt-2">
            Role requerida: {requiredRoles.join(', ')} | Sua role: {user.role}
          </p>
        </div>
      </div>
    );
  }

  // Se for escola e perfil não estiver completo, não renderizar conteúdo
  if (
    requireCompleteProfile &&
    user?.role === 'school' && 
    profileComplete === false
  ) {
    return null; // O redirecionamento será feito pelo useEffect
  }

  return <>{children}</>;
}

